  `buffer_persen` decimal(5,1) DEFAULT 10.0 COMMENT 'Buffer cadangan % (1-10), default 10',
  `berat_per_satuan` decimal(10,2) DEFAULT 0.00 COMMENT 'Berat 1 satuan dalam gram',
  `satuan` varchar(20) NOT NULL,
  `harga_satuan` decimal(15,2) DEFAULT 0.00,
  `harga_sebelumnya` decimal(15,2) DEFAULT 0.00,
  `kalori` decimal(10,2) DEFAULT 0.00,
  `protein` decimal(10,2) DEFAULT 0.00,
  `karbohidrat` decimal(10,2) DEFAULT 0.00,
  `lemak` decimal(10,2) DEFAULT 0.00,
  `serat` decimal(10,2) DEFAULT 0.00,
  `stok_saat_ini` decimal(15,3) DEFAULT 0.000,
  `stok_minimum` decimal(15,3) DEFAULT 0.000,
  `sumber` varchar(20) DEFAULT NULL COMMENT 'sumber permintaan: ahli_gizi',
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_id_koperasi` (`id_koperasi`),
  KEY `idx_bahan_baku_tenant_nama` (`tenant_id`,`nama`),
  CONSTRAINT `bahan_baku_ibfk_1` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=246 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

